const body = $input.first().json.body || {};

const sessionId = String(body.session_id || 'anonymous-' + Date.now()).substring(0, 100);

// Sanitize message: strip control chars, trim, enforce length limit
let message = String(body.message || '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '').trim();
if (message.length > 2000) message = message.substring(0, 2000);

const userEmail = body.email ? String(body.email).substring(0, 254) : null;
const userName = body.name ? String(body.name).substring(0, 100) : null;

// Validate language — only allow known values
const allowedLangs = ['lt', 'en'];
const rawLang = String(body.language || 'lt').toLowerCase().substring(0, 2);
const browserLang = allowedLangs.indexOf(rawLang) !== -1 ? rawLang : 'lt';

return [{
  json: {
    sessionId,
    message,
    userEmail,
    userName,
    browserLang,
    chatInput: message || 'Sveiki'
  }
}];

const agentOutput = $input.first().json || {};
let response = agentOutput.output || agentOutput.text || '';

if (!response || !response.trim()) {
  return [{ json: { enriched: 'Atsiprašome, šiuo metu negaliu atsakyti. Susisiekite tiesiogiai: +370 648 803 88 arba info@batutynas.lt' } }];
}

// Idempotency: skip if already enriched
if (response.startsWith('{{HTML}}')) {
  return [{ json: { enriched: response } }];
}

